window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-226a8d4e5ce7e93d"]={"versions": [{"id": "FIG-226a8d4e5ce7e93d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Metamodell-Elementen für Post-Build-Variantenkriterien im Kontext der AUTOSAR Generic Structure Template (GST). Das Diagramm definiert die statische Struktur und Assoziation zwischen dem Variantenkriterium und der zugehörigen Umrechnungsmethode.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei Klassen und eine gerichtete Assoziation:</p>\n<ul class=\"fig-list\"><li><strong>PostBuildVariantCriterion</strong>: Als <code>ARElement</code> gekennzeichnetes Modellelement zur Repräsentation eines Kriteriums für Post-Build-Variabilität.\n</li><li><strong>ComputationMethod::CompuMethod</strong>: Als <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> typisierte Klasse aus dem Paket <code>ComputationMethod</code>. Sie verfügt über das Attribut:\n<ul class=\"fig-list\"><li><code>+ displayFormat: DisplayFormatString [0..1]</code>\n</li></ul>\n</li><li><strong>Assoziation</strong>: Gerichtete Referenz von <code>PostBuildVariantCriterion</code> auf <code>CompuMethod</code> mit der Zielrolle <code>+compuMethod</code> ohne explizite Multiplizitätsangabe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des Metamodells; kein dynamisches Laufzeitverhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>PostBuildVariantCriterion</code> referenziert über die Rolle <code>+compuMethod</code> eine Rechen- und Darstellungsregel (<code>CompuMethod</code>), um die Werte des Kriteriums semantisch zu interpretieren und optional über <code>displayFormat</code> zu formatieren. Werkzeuge zur Variantenkonfiguration und Codegenerierung müssen sicherstellen, dass die verlinkte <code>CompuMethod</code> zur Auswertung des Post-Build-Kriteriums aufgelöst werden kann.</p>"}, {"id": "FIG-b851e5e885ffd533", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Metamodell-Elementen für Post-Build-Variantenkriterien im Kontext der AUTOSAR Generic Structure Template (GST). Das Diagramm definiert die statische Struktur und Assoziation zwischen dem Variantenkriterium und der zugehörigen Umrechnungsmethode.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei Klassen und eine gerichtete Assoziation:</p>\n<ul class=\"fig-list\"><li><strong>PostBuildVariantCriterion</strong>: Als <code>ARElement</code> und <code>AtpDefinition</code> gekennzeichnetes Modellelement zur Repräsentation eines Kriteriums für Post-Build-Variabilität.\n</li><li><strong>CompuMethod</strong>: Als <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> typisierte Klasse zur semantischen Wertinterpretation. Sie verfügt über das Attribut:\n<ul class=\"fig-list\"><li><code>+ displayFormat :DisplayFormatString [0..1]</code>\n</li></ul>\n</li><li><strong>Assoziation</strong>: Gerichtete Referenz von <code>PostBuildVariantCriterion</code> auf <code>CompuMethod</code> mit der Zielrolle <code>+compuMethod</code> ohne explizite Multiplizitätsangabe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des Metamodells; kein dynamisches Laufzeitverhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>PostBuildVariantCriterion</code> ist als <code>AtpDefinition</code> qualifiziert und referenziert über <code>+compuMethod</code> eine <code>CompuMethod</code> zur semantischen Interpretation der Kriteriumswerte. Modellierungswerkzeuge müssen die Definitionseigenschaft sowie die referenzierte Umrechnungsmethode bei der Variantenkonfiguration auswerten.</p>"}, {"id": "FIG-defbf5e6e921779b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Metamodell-Elementen für Post-Build-Variantenkriterien im Kontext der AUTOSAR Generic Structure Template (GST). Das Diagramm definiert die statische Struktur und Assoziation zwischen dem Variantenkriterium und der zugehörigen Umrechnungsmethode.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei Klassen und eine gerichtete Assoziation:</p>\n<ul class=\"fig-list\"><li><strong>PostBuildVariantCriterion</strong>: Als <code>ARElement</code> und <code>AtpDefinition</code> gekennzeichnetes Modellelement zur Repräsentation eines Kriteriums für Post-Build-Variabilität.\n</li><li><strong>CompuMethod</strong>: Als <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> typisierte Klasse zur semantischen Wertinterpretation. Sie verfügt über das Attribut:\n<ul class=\"fig-list\"><li><code>+ displayFormat :DisplayFormatString [0..1]</code>\n</li></ul>\n</li><li><strong>Assoziation</strong>: Gerichtete Referenz von <code>PostBuildVariantCriterion</code> auf <code>CompuMethod</code> mit der Zielrolle <code>+compuMethod</code> ohne explizite Multiplizitätsangabe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des Metamodells; kein dynamisches Laufzeitverhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>PostBuildVariantCriterion</code> ist als <code>AtpDefinition</code> qualifiziert und referenziert über <code>+compuMethod</code> eine <code>CompuMethod</code> zur semantischen Interpretation der Kriteriumswerte. Modellierungswerkzeuge müssen die Definitionseigenschaft sowie die referenzierte Umrechnungsmethode bei der Variantenkonfiguration auswerten.</p>"}, {"id": "FIG-00d83467ae4aa9b4", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Metamodell-Elementen für Post-Build-Variantenkriterien im Kontext der AUTOSAR Generic Structure Template (GST). Das Diagramm definiert die statische Struktur und Assoziation zwischen dem Variantenkriterium und der zugehörigen Umrechnungsmethode.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei Klassen und eine gerichtete Assoziation:</p>\n<ul class=\"fig-list\"><li><strong>PostBuildVariantCriterion</strong>: Als <code>ARElement</code> und <code>AtpDefinition</code> gekennzeichnetes Modellelement zur Repräsentation eines Kriteriums für Post-Build-Variabilität.\n</li><li><strong>CompuMethod</strong>: Als <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> typisierte Klasse zur semantischen Wertinterpretation. Sie verfügt über das Attribut:\n<ul class=\"fig-list\"><li><code>+ displayFormat :DisplayFormatString [0..1]</code>\n</li></ul>\n</li><li><strong>Assoziation</strong>: Gerichtete Referenz von <code>PostBuildVariantCriterion</code> auf <code>CompuMethod</code> mit der Zielrolle <code>+compuMethod</code> und der festen Multiplizität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des Metamodells; kein dynamisches Laufzeitverhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>PostBuildVariantCriterion</code> ist als <code>AtpDefinition</code> qualifiziert und verpflichtet über die Multiplizität <code>1</code> an <code>+compuMethod</code> zur Angabe genau einer gültigen <code>CompuMethod</code>. Fehlt diese Referenz, ist das Modell instanzierungs- bzw. schemaschwach und ungültig.</p>"}, {"id": "FIG-bdb2c5d2df0946c4", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Metamodell-Elementen für Post-Build-Variantenkriterien im Kontext der AUTOSAR Generic Structure Template (GST). Das Diagramm definiert die statische Struktur und Assoziation zwischen dem Variantenkriterium und der zugehörigen Umrechnungsmethode.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei Klassen und eine gerichtete Assoziation:</p>\n<ul class=\"fig-list\"><li><strong>PostBuildVariantCriterion</strong>: Als <code>ARElement</code> und <code>AtpDefinition</code> gekennzeichnetes Modellelement zur Repräsentation eines Kriteriums für Post-Build-Variabilität.\n</li><li><strong>CompuMethod</strong>: Als <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> typisierte Klasse zur semantischen Wertinterpretation. Sie verfügt über das Attribut:\n<ul class=\"fig-list\"><li><code>+ displayFormat: DisplayFormatString [0..1]</code>\n</li></ul>\n</li><li><strong>Assoziation</strong>: Gerichtete Referenz von <code>PostBuildVariantCriterion</code> auf <code>CompuMethod</code> mit der Zielrolle <code>+compuMethod</code> und der festen Multiplizität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des Metamodells; kein dynamisches Laufzeitverhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>PostBuildVariantCriterion</code> ist als <code>AtpDefinition</code> qualifiziert und verpflichtet über die Multiplizität <code>1</code> an <code>+compuMethod</code> zur Angabe genau einer gültigen <code>CompuMethod</code>. Fehlt diese Referenz, ist das Modell instanzierungs- bzw. schemaschwach und ungültig.</p>"}], "trans": [{"from": "FIG-226a8d4e5ce7e93d", "to": "FIG-b851e5e885ffd533", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Stereotyp <code>«AtpDefinition»</code> an Klasse <code>PostBuildVariantCriterion</code> ergänzt.\n</li><li>Klassenname <code>ComputationMethod::CompuMethod</code> zu <code>CompuMethod</code> verkürzt (Paketpräfix entfernt).\n</li></ul>"}, {"from": "FIG-b851e5e885ffd533", "to": "FIG-defbf5e6e921779b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-defbf5e6e921779b", "to": "FIG-00d83467ae4aa9b4", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Multiplizität an der Assoziationsrolle <code>+compuMethod</code> von implizit unbestimmt/1 auf explizit <code>1</code> gesetzt.\n</li></ul>"}, {"from": "FIG-00d83467ae4aa9b4", "to": "FIG-bdb2c5d2df0946c4", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Minimaler Weißraum-/Interpunktionsabgleich beim Attribut <code>+ displayFormat: DisplayFormatString [0..1]</code> (Abstand vor dem Doppelpunkt entfernt).\n</li></ul>"}]};
